	@Query(value="WITH\n"
			+ "			    Approved_Count AS (\n"
			+ "			        SELECT COUNT(DISTINCT p.project_id) AS ct\n"
			+ "			        FROM projects p \n"
			+ "			        INNER JOIN teams t ON p.project_id = t.project_id \n"
			+ "			        INNER JOIN employee_team_mapping etm ON etm.team_id = t.team_id \n"
			// + "inner join project_po_details ppo ON ppo.project_id = p.project_id \n"
            // + "inner join po_department_mapping pdm on pdm.po_id = ppo.po_id \n"
//			+ "			        INNER JOIN project_department_map pdm ON p.project_id = pdm.project_id\n"
			// + "left join project_po_details ppo ON ppo.project_id = p.project_id \n"
			+"LEFT JOIN project_po_details ppo \n" 
			+"ON ppo.project_id = p.project_id and ppo.active = true \n" 
			+"AND ppo.po_start_date <= current_timestamp \n" 
			+"AND ( (ppo.po_end_date IS NULL OR ppo.po_end_date >= current_timestamp) \n"
			+" or \n" 
			+" (\n"  //
			+" ppo.po_end_date < current_timestamp() \n"  //
			+" and not exists( \n" 
			+" select 1 from project_po_details ppd1\n" 
			+" where ppd1.project_id = ppo.project_id\n"
			+" and ppd1.po_start_date <= current_timestamp()\n" 
			+" and (ppd1.po_end_date is null or ppd1.po_end_date >= current_timestamp())\n" 
			+" )\n" 
			+" and DATE(ppo.po_end_date) = (\n" 
			+" Select distinct Max(DATE(ppd0.po_end_date))\n" 
			+" FROM project_po_details ppd0\n" 
			+" WHERE ppd0.project_id = ppo.project_id\n" 
			+" AND ppd0.po_end_date < current_timestamp()\n" 
			+" )\n" 
			+" ))\n"
			+" inner join po_department_mapping pdm on \n"
			+" ((ppo.po_id IS NOT NULL AND pdm.po_id = ppo.po_id)\n" 
			+" OR (ppo.po_id IS NULL AND pdm.project_id = p.project_id)) \n"
			+" WHERE p.active = 'true' \n"
			+" AND t.is_active = 'Y' \n"
			+ "AND etm.active != 0\n"
			+ "AND p.is_draft_project = 'false'\n"
			+ "AND (pdm.dept_id IN (:deptIds))\n"
			+ "),\n"
			+ "\n"
			+ "			Not_Started_Count AS (\n"
			+ "SELECT COUNT(DISTINCT p.project_id) AS ct\n"
			+ "FROM projects p \n"
			// + "inner join project_po_details ppo ON ppo.project_id = p.project_id \n"
            // + "inner join po_department_mapping pdm on pdm.po_id = ppo.po_id \n"
//			+ "			        INNER JOIN project_department_map pdm ON pdm.project_id = p.project_id \n"
			// + "left join project_po_details ppo ON ppo.project_id = p.project_id \n"
			+ "		LEFT JOIN project_po_details ppo \n"
			+ "		ON ppo.project_id = p.project_id and ppo.active = true \n"
			+ "		AND ppo.po_end_date > CURRENT_TIMESTAMP \n"
			+ "inner join po_department_mapping pdm on \n"
			+ "((ppo.po_id IS NOT NULL AND pdm.po_id = ppo.po_id)\n"
			+ "OR (ppo.po_id IS NULL AND pdm.project_id = p.project_id)) \n"
			+ "			        WHERE p.active = 'true' \n"
			+ "			          AND p.is_draft_project IS NULL \n"
			+ "			          AND (p.status != 'Completed' OR p.status IS NULL)\n"
			+ "			          AND NOT EXISTS (SELECT 1 FROM teams t WHERE t.project_id = p.project_id) \n"
			+ "			          AND (p.internal_project_type IS NOT NULL OR DATE(p.end_date) > CURDATE())\n"
			+ "			          AND (pdm.dept_id IN (:deptIds))\n"
			+ "			    ),\n"
			+ "			\n"
			+ "			    Pending_Approval_Count AS (\n"
			+ "			        SELECT COUNT(DISTINCT p.project_id) AS ct\n"
			+ "			        FROM projects p \n"
			// + "inner join project_po_details ppo ON ppo.project_id = p.project_id \n"
            // + "inner join po_department_mapping pdm on pdm.po_id = ppo.po_id \n"
		   //  + "INNER JOIN project_department_map pdm ON pdm.project_id = p.project_id \n"
           +"LEFT JOIN project_po_details ppo \n" 
			+"ON ppo.project_id = p.project_id and ppo.active = true \n" 
			+"AND ppo.po_start_date <= current_timestamp \n" 
			+"AND ( (ppo.po_end_date IS NULL OR ppo.po_end_date >= current_timestamp) \n"
			+" or \n" 
			+" (\n"  //
			+" ppo.po_end_date < current_timestamp() \n"  //
			+" and not exists( \n" 
			+" select 1 from project_po_details ppd1\n" 
			+" where ppd1.project_id = ppo.project_id\n"
			+" and ppd1.po_start_date <= current_timestamp()\n" 
			+" and (ppd1.po_end_date is null or ppd1.po_end_date >= current_timestamp())\n" 
			+" )\n" 
			+" and DATE(ppo.po_end_date) = (\n" 
			+" Select distinct Max(DATE(ppd0.po_end_date))\n" 
			+" FROM project_po_details ppd0\n" 
			+"              WHERE ppd0.project_id = ppo.project_id\n" 
			+"                AND ppd0.po_end_date < current_timestamp()\n" 
			+" )\n" 
			+" ))\n"
			+ "inner join po_department_mapping pdm on \n"
			+ "((ppo.po_id IS NOT NULL AND pdm.po_id = ppo.po_id)\n" 
			+ "OR (ppo.po_id IS NULL AND pdm.project_id = p.project_id)) \n"
			+ "			        WHERE p.active = 'true' \n"
			+ "			          AND p.is_draft_project = 'true'\n"
			+ "			          AND (pdm.dept_id IN (:deptIds))\n"
			+ "			    ),\n"
			+ "			\n"
			+ "			    Rejected_Count AS (\n"
			+ "			        SELECT COUNT(DISTINCT p.project_id) AS ct\n"
			+ "			        FROM projects p \n"
			// + "inner join project_po_details ppo ON ppo.project_id = p.project_id \n"
            // + "inner join po_department_mapping pdm on pdm.po_id = ppo.po_id \n"
			// + "INNER JOIN project_department_map pdm ON pdm.project_id = p.project_id \n"
			+"LEFT JOIN project_po_details ppo \n" 
			+"ON ppo.project_id = p.project_id and ppo.active = true \n" 
			+"AND ppo.po_start_date <= current_timestamp \n" 
			+"AND ( (ppo.po_end_date IS NULL OR ppo.po_end_date >= current_timestamp) \n"
			+" or \n" 
			+" (\n"  //
			+" ppo.po_end_date < current_timestamp() \n"  //
			+" and not exists( \n" 
			+" select 1 from project_po_details ppd1\n" 
			+" where ppd1.project_id = ppo.project_id\n"
			+" and ppd1.po_start_date <= current_timestamp()\n" 
			+" and (ppd1.po_end_date is null or ppd1.po_end_date >= current_timestamp())\n" 
			+" )\n" 
			+" and DATE(ppo.po_end_date) = (\n" 
			+" Select distinct Max(DATE(ppd0.po_end_date))\n" 
			+" FROM project_po_details ppd0\n" 
			+"              WHERE ppd0.project_id = ppo.project_id\n" 
			+"                AND ppd0.po_end_date < current_timestamp()\n" 
			+" )\n" 
			+" ))\n"
			+ "inner join po_department_mapping pdm on \n"
			+ "( (ppo.po_id IS NOT NULL AND pdm.po_id = ppo.po_id)\n"
			+ "OR (ppo.po_id IS NULL AND pdm.project_id = p.project_id) ) \n"
			+ "			        WHERE p.active = 'true' \n"
			+ "			          AND UPPER(p.is_draft_project) = 'REJECTED'\n"
			+ "			          AND (pdm.dept_id IN (:deptIds))\n"
			+ "			    )\n"
			+ "			\n"
			+ "			SELECT\n"
			+ "			    (SELECT ct FROM Approved_Count) +\n"
			+ "			    (SELECT ct FROM Not_Started_Count) +\n"
			+ "			    (SELECT ct FROM Pending_Approval_Count) +\n"
			+ "			    (SELECT ct FROM Rejected_Count) AS total_project_count;" , nativeQuery = true)
	Integer getAllTotalProjectCount(List<Long> deptIds);
	
	
