	@Query(value="select  count( Distinct p.projectId) from Project p \n"
	+ "LEFT JOIN ProjectPoDetails ppd \n"
	+ "       ON ppd.projectId = p.projectId and ppd.active = true and  ppd.poStartDate <= CURRENT_TIMESTAMP \n"
	+ " and ( (ppd.poEndDate IS NULL or ppd.poEndDate >= CURRENT_TIMESTAMP)  \n"
	+ " or ( ppd.poEndDate < CURRENT_TIMESTAMP\n" 
	+		"AND NOT EXISTS (\n" 
	+		"SELECT 1\n" 
	+		"FROM ProjectPoDetails ppd1\n" 
	+		"WHERE ppd1.projectId = ppd.projectId\n" 
	+		"AND ppd1.poStartDate <= CURRENT_TIMESTAMP\n" 
	+		"AND (ppd1.poEndDate IS NULL OR ppd1.poEndDate >= CURRENT_TIMESTAMP)\n" 
	+		")\n" 
	+		"AND  FUNCTION('DATE', ppd.poEndDate) = ( \n"                
	+ 		"SELECT distinct MAX(FUNCTION('DATE',ppd2.poEndDate)) \n"    
	+		"FROM ProjectPoDetails ppd2 \n"     
	+ 		"WHERE ppd2.projectId = ppd.projectId \n"
	+        "AND ppd2.poStartDate <= CURRENT_TIMESTAMP\n"
	+ ") \n"
	+ " )) \n"			// + "left join PoDepartmentMapping pdm on pdm.poId = ppo.poId \n"
			+ "inner join PoDepartmentMapping pdm on \n"
			+ "( (ppd.poId IS NOT NULL AND pdm.poId = ppd.poId)\n" 
			+ "OR (ppd.poId IS NULL AND pdm.projectId = p.projectId) ) \n"
			+ "where  p.projectStatus = 'Completed' and pdm.deptId IN :deptIds")
	Integer getAllCompletedProjectCountInIshine(@Param("deptIds") List<Long> deptIds);
	
	@Transactional
	@Modifying
    @Query(value = "CALL sp_SyncProjectsFromTemp", nativeQuery = true)
    void callSyncProjectsSP();
	
	
	

	@Query(value = "select count(distinct p.project_id) from projects p\n"
			+ "left join project_po_details ppo ON ppo.project_id = p.project_id and ppo.active = true and ppo.po_start_date <= CURRENT_TIMESTAMP\n"
            + "and ( (ppo.po_end_date IS NULL or ppo.po_end_date >= CURRENT_TIMESTAMP))  \n"
			// + "inner join po_department_mapping pdm on pdm.po_id = ppo.po_id \n"
//			+ "INNER JOIN project_department_map pd ON p.project_id = pd.project_id\n"
            + "inner join po_department_mapping pdm on \n"
			+ "((ppo.po_id IS NOT NULL AND pdm.po_id = ppo.po_id)\n" 
			+ "OR (ppo.po_id IS NULL AND pdm.project_id = p.project_id)) \n"
			+ "INNER JOIN department d ON pdm.dept_id = d.dept_id\n"
			+ "INNER JOIN teams t ON p.project_id = t.project_id\n"
			+ "INNER JOIN employee_team_mapping etm ON t.team_id = etm.team_id\n"
			+ "INNER JOIN clients c ON p.client_id = c.client_id\n"
			+ "LEFT JOIN project_manager_mapping pm on p.project_id = pm.project_id\n"
			+ " LEFT JOIN employee e1 on e1.emp_id = pm.project_manager_id \n"
			+ " left JOIN job_role j1 on j1.job_role_id = e1.job_role_id \n"
			+ " left JOIN department d1 on d1.dept_id = j1.dept_id\n"
			+ "WHERE etm.active != 0 AND t.is_active != 'N' AND p.active != 'false' and po_project_type = 'TNM'\n"
			+ " and d.dept_id in (:deptIds)" , nativeQuery = true)
	Integer getAllActiveTNMProjectsCount(@Param("deptIds") List<Long> deptIds);
	
	
	
