	// 		+ "					    		    AND (:clientName IS NULL OR LOWER(pls.client_name) LIKE CONCAT('%', :clientName, '%'))\n"
	// 		+ "					    		    AND (:apmosysRM IS NULL OR LOWER(pls.apmosysrm) LIKE CONCAT('%', :apmosysRM, '%'))\n"
