	List<Object[]> getAllTotalProjectList(@Param("deptIds") List<Long> deptIds);
	

	@Query(value = "SELECT\n"
		    + " distinct p.project_id,project_name, \n"
			+ " GROUP_CONCAT(DISTINCT ppd.po_no ORDER BY p.start_date   SEPARATOR ', ') AS po_no,\n"
			+ " p.client_id, p.po_project_id, p.active,po_project_type,\n"
		    + " GROUP_CONCAT(DISTINCT e1.name ORDER BY e1.name SEPARATOR ', ') as Project_Manager,\n"
		    + " c.client_name,\n"
			+ " GROUP_CONCAT(DISTINCT ppd.client_rm ORDER BY p.start_date SEPARATOR ', ') AS clientrm,\n"
			+ " p.dept_id,\n"
			+ " GROUP_CONCAT(DISTINCT ppd.apmosys_rm ORDER BY p.start_date SEPARATOR ', ') AS apmosysrm,\n"
			+ " date(p.start_date) start_date, date(p.end_date) end_date,\n"
		    + " p.state, p.created_on, p.status PO_project_status,p.project_completion_date,p.project_status Ishine_project_status, p.internal_project_type,\n"
		    + " CASE \n"
		    + " WHEN p.is_draft_project = 'true' THEN 'Pending For Approval' \n"
		    + " WHEN p.is_draft_project = 'false' THEN 'Approved' \n"
		    + " WHEN p.is_draft_project = 'Rejected' THEN 'Rejected' \n"
		    + " WHEN p.is_draft_project = 'Completed' THEN 'Completed' \n"
		    + " WHEN p.is_draft_project IS NULL THEN 'Not Started' \n"
		    + " ELSE 'Un Mentioned Test Data' \n"
		    + " END as Approval_status, \n"
		    + " CASE \n"
		    + " WHEN p.po_project_id IS NOT NULL THEN CONCAT('po', p.po_project_id)\n"
		    + " ELSE CAST(p.project_id AS CHAR) \n"
		    + " END AS projectViewId, \n"
		    + " GROUP_CONCAT(DISTINCT d.name ORDER BY d.name SEPARATOR ', ') AS department_names\n"
		    + "FROM projects p\n"
			+ " LEFT JOIN project_po_details ppd \n"
			+ " ON ppd.project_id = p.project_id and ppd.active = true \n"
			+ "AND ppd.po_start_date <= current_timestamp \n" 
			+ "AND (ppd.po_end_date IS NULL OR ppd.po_end_date  >= current_timestamp ) \n"
		    // + "INNER JOIN project_department_map pd ON p.project_id = pd.project_id\n"
			// + "inner join po_department_mapping pdm on pdm.po_id = ppd.po_id \n"
			+ "inner join po_department_mapping pdm on \n"
			+ "( (ppd.po_id IS NOT NULL AND pdm.po_id = ppd.po_id)\n" 
			+ "OR (ppd.po_id IS NULL AND pdm.project_id = p.project_id) ) \n"
		    + " INNER JOIN department d ON pdm.dept_id = d.dept_id \n"
		    + " INNER JOIN teams t ON p.project_id = t.project_id \n"
		    + " INNER JOIN employee_team_mapping etm ON t.team_id = etm.team_id \n"
		    + " INNER JOIN clients c ON p.client_id = c.client_id \n"
		    + " LEFT JOIN project_manager_mapping pm on p.project_id = pm.project_id\n"
		    + " LEFT JOIN employee e1 on e1.emp_id = pm.project_manager_id \n"
		    + " LEFT JOIN job_role j1 on j1.job_role_id = e1.job_role_id \n"
		    + " LEFT JOIN department d1 on d1.dept_id = j1.dept_id\n"
		    + "WHERE 1=1\n"
		    + " and po_project_type = 'TNM' \n"
		    + " and d.dept_id in (:deptIds)\n"
		    + "AND etm.active != 0 AND t.is_active != 'N' AND p.active != 'false'\n"
		    + " GROUP BY p.project_id, project_name, p.client_id, p.po_project_id, p.active, po_project_type, c.client_name,"
		    + "  p.dept_id, start_date, end_date, p.state, p.created_on, "
		    + "p.status, p.project_completion_date, p.project_status, p.internal_project_type", nativeQuery = true)
		List<Object[]> getAllActiveTNMProjectsList(@Param("deptIds") List<Long> deptIds);


		@Query(value = "SELECT\n"
				+ "	distinct p.project_id,project_name,\n"
				+ " GROUP_CONCAT(DISTINCT ppd.po_no ORDER BY p.start_date SEPARATOR ', ') AS po_no,\n"
				+ "	p.client_id, p.po_project_id, p.active,po_project_type,\n"
				+ "	GROUP_CONCAT(DISTINCT e1.name ORDER BY e1.name SEPARATOR ', ') as Project_Manager,\n"
				+ "	c.client_name,\n"
				+ " GROUP_CONCAT(DISTINCT ppd.client_rm ORDER BY p.start_date SEPARATOR ', ') AS clientrm,\n"
				+ " p.dept_id,\n"
				+ " GROUP_CONCAT(DISTINCT ppd.apmosys_rm ORDER BY p.start_date SEPARATOR ', ') AS apmosysrm,\n"
				+ " date(p.start_date) start_date, date(p.end_date) end_date,\n"
				+ "	p.state, p.created_on, p.status PO_project_status,p.project_completion_date,p.project_status Ishine_project_status, p.internal_project_type,\n"
				+ "	CASE \n"
				+ "	WHEN p.is_draft_project = 'true' THEN 'Pending For Approval' \n"
				+ "	WHEN p.is_draft_project = 'false' THEN 'Approved' \n"
				+ "	WHEN p.is_draft_project = 'Rejected' THEN 'Rejected' \n"
				+ "	WHEN p.is_draft_project = 'Completed' THEN 'Completed' \n"
				+ "	WHEN p.is_draft_project = null THEN 'Not Started' \n"
				+ "	ELSE 'Un Mentioned Test Data' \n"
				+ "	END as Approval_status, \n"
				+ "	CASE \n"
				+ "	WHEN p.po_project_id IS NOT NULL THEN CONCAT('po', p.po_project_id)\n"
				+ "	ELSE CAST(p.project_id AS CHAR) \n"
				+ "	END AS projectViewId , \n"
				+ "	GROUP_CONCAT(DISTINCT d.name ORDER BY d.name SEPARATOR ', ') AS department_names\n"
				+ "	FROM projects p\n"
				+ "	LEFT JOIN project_po_details ppd ON ppd.project_id = p.project_id AND ppd.active = true AND DATE(ppd.po_start_date) >= STR_TO_DATE(:fromDate, '%Y-%m-%d') AND DATE(ppd.po_end_date) <= STR_TO_DATE(:toDate, '%Y-%m-%d') \n"
				+ " INNER join po_department_mapping pdm on ((ppd.po_id IS NOT NULL AND pdm.po_id = ppd.po_id) \n"
				+ "	 OR (ppd.po_id IS NULL AND pdm.project_id = p.project_id) ) \n"
				+ "	INNER JOIN department d ON pdm.dept_id = d.dept_id \n"
				+ "	INNER JOIN teams t ON p.project_id = t.project_id \n"
				+ "	INNER JOIN employee_team_mapping etm ON t.team_id = etm.team_id \n"
				+ "	INNER JOIN clients c ON p.client_id = c.client_id \n"
				+ "	INNER JOIN project_manager_mapping pm on p.project_id = pm.project_id\n"
				+ "	LEFT JOIN employee e1 on e1.emp_id = pm.project_manager_id\n"
				+ "	LEFT JOIN job_role j1 on j1.job_role_id = e1.job_role_id \n"
				+ "	LEFT JOIN department d1 on d1.dept_id = j1.dept_id\n"
				+ "	WHERE \n"
				+ "	po_project_type = 'TNM' \n"
				+ " AND etm.active != 0 AND t.is_active != 'N' AND p.active != 'false' \n"
				+ "	AND d.dept_id in (:deptIds) \n"
				+ "	AND DATE(p.end_date) < CURDATE() \n"
				+ "	AND DATE(p.end_date) between STR_TO_DATE(:fromDate, '%Y-%m-%d') and STR_TO_DATE(:toDate, '%Y-%m-%d') \n"
				+ "	GROUP BY \n"
				+ "	p.project_id,project_name,p.client_id, p.po_project_id, p.active, po_project_type, c.client_name, p.dept_id,  \n"
				+ "	start_date, end_date, p.state, p.created_on, p.status,p.project_completion_date,p.project_status, \n"
				+ "	p.internal_project_type", nativeQuery = true)
		List<Object[]> getExpiredProjectList(@Param("deptIds") List<Long> deptIds,
				@Param("fromDate") String fromDate, @Param("toDate") String toDate);

		@Query("SELECT new com.apmosys.employeeportal.dto.ExpiredPoDto(" +
		"ppd.poNo, " +
		"p.projectName, " +
		"p.endDate, " +
		"ppd.apmosysRM, " +
		"c.clientName, " +
		"ppd.clientRm, " +
		"DATEDIFF(CURRENT_DATE, p.endDate)) " +
		"FROM Project p " +
		"		LEFT JOIN ProjectPoDetails ppd \n"+
		"		ON ppd.projectId = p.projectId and ppd.active = true \n"+
		"		AND FUNCTION('DATE', ppd.poEndDate) = ( \n"          +      // CHANGED: latest PO selection
		"		SELECT MAX(FUNCTION('DATE',ppd2.poEndDate)) \n"   +  // CHANGED
		"		FROM ProjectPoDetails ppd2 \n"   +  // CHANGED
		"		WHERE ppd2.projectId = p.projectId \n"+
		"		) \n "+
		// "JOIN ProjectDepartmentMap pd ON p.projectId = pd.projectId " +
		// "JOIN PoDepartmentMapping pd ON ppd.poId = pd.poId " +
		 "inner join PoDepartmentMapping pd on \n"+
         "( (ppd.poId IS NOT NULL AND pd.poId = ppd.poId)\n" +
         "OR (ppd.poId IS NULL AND pd.projectId = p.projectId) ) \n"+
		"JOIN Department d ON pd.deptId = d.deptId " +
		"JOIN Team t ON p.projectId = t.projectId " +
		"JOIN EmployeeTeamMap etm ON t.teamId = etm.teamId " +
		"JOIN Client c ON p.clientId = c.clientId " +
		"JOIN ProjectManagerMapping pm ON p.projectId = pm.projectId " +
		"LEFT JOIN Employee e1 ON e1.empId = pm.projectManagerId " +
		"LEFT JOIN JobRole j1 ON j1.jobRoleId = e1.jobRoleId " +
		"LEFT JOIN Department d1 ON d1.deptId = j1.deptId " +
		"WHERE p.poProjectType = 'TNM' " +
		"AND etm.active != 0 " +
		"AND t.isActive != 'N' " +
		"AND p.active != 'false' " +
		"AND p.endDate < CURRENT_DATE")
 List<ExpiredPoDto> getAllExpiredTNMProject();


 @Query(value = " WITH RelevantProjects AS (\n"
 + "	select distinct p.project_id,p.project_name,\n"
 +  " 			 GROUP_CONCAT(DISTINCT ppd.po_no ORDER BY p.start_date   SEPARATOR ', ') AS po_no,\n"
 + " p.client_id, p.po_project_id, p.active,po_project_type, \n"
 + "     group_concat(distinct e1.name order by e1.name separator ', ') as Project_Manager,\n"
 + "	 c.client_name,\n"
 + " GROUP_CONCAT(DISTINCT ppd.client_rm ORDER BY p.start_date SEPARATOR ', ') AS clientrm,\n" 
 + "p.dept_id,\n"
 + "GROUP_CONCAT(DISTINCT ppd.apmosys_rm ORDER BY p.start_date SEPARATOR ', ') AS apmosysrm,\n" 
 + " date(p.start_date) start_date, date(p.end_date) end_date,\n"
 + "	 p.state, p.created_on, p.status PO_project_status,p.project_completion_date,p.project_status Ishine_project_status, p.internal_project_type,\n"
 + "	  CASE \n"
 + "	 WHEN p.is_draft_project = 'true' THEN 'Pending For Approval' \n"
 + "	 WHEN p.is_draft_project = 'false' THEN 'Approved' \n"
 + "	 WHEN p.is_draft_project = 'Rejected' THEN 'Rejected' \n"
 + "	 WHEN p.is_draft_project = 'Completed' THEN 'Completed' \n"
 + "	 WHEN p.is_draft_project is null THEN 'Not Started' \n"
 + "	 ELSE 'Un Mentioned Test Data' \n"
 + "	 END as Approval_status, \n"
 + "	  CASE \n"
 + "	   WHEN p.po_project_id IS NOT NULL THEN CONCAT('po', p.po_project_id)\n"
 + "	   ELSE CAST(p.project_id AS CHAR) \n"
 + "	   END AS projectViewId  \n"
 + "	   FROM projects p\n"
 + "	   LEFT JOIN project_po_details ppd \n"
 + " 	   ON ppd.project_id = p.project_id and ppd.active = true \n"
 + "	   AND ppd.po_start_date <= current_timestamp \n" 
 + "AND (ppd.po_end_date IS NULL OR ppd.po_end_date >= current_timestamp ) \n"
//  + "inner join po_department_mapping pdm on pdm.po_id = ppd.po_id \n"
//  + "	  left JOIN project_department_map pd ON p.project_id = pd.project_id\n"
+ "inner join po_department_mapping pdm on \n"
			+ "( (ppd.po_id IS NOT NULL AND pdm.po_id = ppd.po_id)\n" 
			+ "OR (ppd.po_id IS NULL AND pdm.project_id = p.project_id) ) \n"
 + "	  inner JOIN department d ON pdm.dept_id = d.dept_id \n"
 + "	  inner JOIN teams t ON p.project_id = t.project_id \n"
 + "	  inner JOIN employee_team_mapping etm ON t.team_id = etm.team_id \n"
 + "	  LEFT JOIN clients c ON p.client_id = c.client_id \n"
 + "	  LEFT JOIN project_manager_mapping pm on p.project_id = pm.project_id\n"
 + "	  LEFT JOIN employee e1 on e1.emp_id = pm.project_manager_id \n"
 + "      WHERE p.po_project_type = 'TNM'\n"
 + "			AND p.active != 'false'\n"
 + "			AND t.is_active != 'N'\n"
//	 		+ "            --  AND etm.active != 0\n"
 + "	  GROUP BY\n"
 + "	  p.project_id,project_name ,p.client_id, p.po_project_id, p.active, po_project_type, c.client_name, p.dept_id,  \n"
 + "	  start_date, end_date, p.state, p.created_on, p.status,p.project_completion_date,p.project_status, p.internal_project_type \n"
 + "),\n"
 + "\n"
 + "FilledCounts AS (\n"
 + "    SELECT\n"
 + "        etm.resource_overview_id,\n"
 + "        COUNT(DISTINCT etm.emp_id) AS filled_count\n"
 + "    FROM \n"
 + "        employee_team_mapping etm\n"
 + "    INNER JOIN\n"
 + "        teams t ON etm.team_id = t.team_id\n"
 + "    INNER JOIN\n"
 + "        employee e ON etm.emp_id = e.emp_id\n"
 + "     INNER JOIN\n"
 + "        projects p ON p.project_id = t.project_id   \n"
 + "    WHERE 1=1\n"
 + "        -- and etm.active != 0\n"
 + "        AND t.is_active != 'N'\n"
 + "        AND e.employmentstatus != 'InActive'\n"
 + "        and p.po_project_type = 'TNM'\n"
 + "        AND p.active != 'false'\n"
 + "        AND etm.resource_overview_id IS NOT NULL\n"
 + "    GROUP BY \n"
 + "        etm.resource_overview_id\n"
 + "),\n"
 + "\n"
 + "TotalRequirements AS (\n"
 + "	select dept_id, project_id, sum(required_count) as required_count from \n"
 + "	(    SELECT distinct \n"
 + "			d.dept_id, \n"
 + "			rp.project_id,\n"
 + "			rr.count AS required_count,\n"
 + "			role\n"
 + "		FROM\n"
 + "			RelevantProjects rp\n"
 + "		INNER JOIN\n"
 + "			resource_requirement rr ON rp.project_id = rr.project_id \n"
 + "			inner join department d on d.name = rr.department \n"
 + "	) req\n"
 + "		GROUP BY\n"
 + "			dept_id, project_id\n"
 + "),\n"
 + "\n"
 + "UnfilledPositions AS (\n"
 + "    SELECT\n"
 + "        rp.project_id,\n"
 + "        SUM(GREATEST(0, rr.count - IFNULL(fc.filled_count, 0))) AS unfilled_count\n"
 + "    FROM\n"
 + "        RelevantProjects rp\n"
 + "    INNER JOIN\n"
 + "        resource_requirement rr ON rp.project_id = rr.project_id\n"
 + "    LEFT JOIN\n"
 + "        FilledCounts fc ON rr.resource_overview_id = fc.resource_overview_id\n"
 + "    GROUP BY\n"
 + "        rp.project_id\n"
 + ")\n"
 + "\n"
 + "SELECT count(distinct rp.project_id)  \n"
 + "FROM\n"
 + "    RelevantProjects rp \n"
 + "INNER JOIN\n"
 + "    TotalRequirements tr ON rp.project_id = tr.project_id\n"
 + "INNER JOIN \n"
 + "    UnfilledPositions up ON rp.project_id = up.project_id\n"
 + "    where IFNULL(tr.required_count, 0) > IFNULL(up.unfilled_count, 0)\n"
 + "    and rp.dept_id in (:deptIds) \n"
 + "    and up.unfilled_count > 0", 
	nativeQuery = true)
Integer getUnfilledPositionsCount(@Param("deptIds") List<Long> deptIds);

@Query(value = "WITH RelevantProjects AS (  \n"
+ "	select distinct p.project_id,p.project_name,\n"
+ " GROUP_CONCAT(DISTINCT ppd.po_no ORDER BY p.start_date   SEPARATOR ', ') AS po_no,\n" 
+" p.client_id, p.po_project_id, p.active,po_project_type, \n"
+ "     group_concat(distinct e1.name order by e1.name separator ', ') as Project_Manager,\n"
+ "	 c.client_name,\n"
+ " GROUP_CONCAT(DISTINCT ppd.client_rm ORDER BY p.start_date SEPARATOR ', ') AS clientrm,\n" 
+ " p.dept_id,\n"
+ "GROUP_CONCAT(DISTINCT ppd.apmosys_rm ORDER BY p.start_date SEPARATOR ', ') AS apmosysrm,\n" 
+ " date(p.start_date) start_date, date(p.end_date) end_date,\n"
+ "	 p.state, p.created_on, p.status PO_project_status,p.project_completion_date,p.project_status Ishine_project_status, p.internal_project_type,\n"
+ "	  CASE \n"
+ "	 WHEN p.is_draft_project = 'true' THEN 'Pending For Approval' \n"
+ "	 WHEN p.is_draft_project = 'false' THEN 'Approved' \n"
+ "	 WHEN p.is_draft_project = 'Rejected' THEN 'Rejected' \n"
+ "	 WHEN p.is_draft_project = 'Completed' THEN 'Completed' \n"
+ "	 WHEN p.is_draft_project is null THEN 'Not Started' \n"
+ "	 ELSE 'Un Mentioned Test Data' \n"
+ "	 END as Approval_status, \n"
+ "	  CASE \n"
+ "	   WHEN p.po_project_id IS NOT NULL THEN CONCAT('po', p.po_project_id)\n"
+ "	   ELSE CAST(p.project_id AS CHAR) \n"
+ "	   END AS projectViewId,\n"
+ "	GROUP_CONCAT(DISTINCT d.name ORDER BY d.name SEPARATOR ', ') AS department_names \n"
+ "	   FROM projects p\n"
+ "	   LEFT JOIN project_po_details ppd \n"
+ " 	   ON ppd.project_id = p.project_id and ppd.active = true \n"
+ "	  AND ppd.po_start_date <= current_timestamp \n" 
+ "	  AND (ppd.po_end_date IS NULL OR ppd.po_end_date >= current_timestamp ) \n"
// + "	  left JOIN project_department_map pd ON p.project_id = pd.project_id\n"
// + "inner join po_department_mapping pdm on pdm.po_id = ppd.po_id \n"
+ "inner join po_department_mapping pdm on \n"
			+ "( (ppd.po_id IS NOT NULL AND pdm.po_id = ppd.po_id)\n" 
			+ "OR (ppd.po_id IS NULL AND pdm.project_id = p.project_id) ) \n"
+ "	  inner JOIN department d ON pdm.dept_id = d.dept_id \n"
+ "	  inner JOIN teams t ON p.project_id = t.project_id \n"
+ "	  inner JOIN employee_team_mapping etm ON t.team_id = etm.team_id \n"
+ "	  LEFT JOIN clients c ON p.client_id = c.client_id \n"
+ "	  LEFT JOIN project_manager_mapping pm on p.project_id = pm.project_id\n"
+ "	  LEFT JOIN employee e1 on e1.emp_id = pm.project_manager_id \n"
+ "      WHERE p.po_project_type = 'TNM'\n"
+ "			AND p.active != 'false'\n"
+ "			AND t.is_active != 'N'\n"
+ "            --  AND etm.active != 0\n"
+ "	  GROUP BY\n"
+ "	  p.project_id,project_name,p.client_id, p.po_project_id, p.active, po_project_type, c.client_name, p.dept_id, \n"
+ "	  start_date, end_date, p.state, p.created_on, p.status,p.project_completion_date,p.project_status, p.internal_project_type \n"
+ "),\n"
+ "\n"
+ "FilledCounts AS (\n"
+ "    SELECT\n"
+ "        etm.resource_overview_id,\n"
+ "        COUNT(DISTINCT etm.emp_id) AS filled_count\n"
+ "    FROM \n"
+ "        employee_team_mapping etm\n"
+ "    INNER JOIN\n"
+ "        teams t ON etm.team_id = t.team_id\n"
+ "    INNER JOIN\n"
+ "        employee e ON etm.emp_id = e.emp_id\n"
+ "     INNER JOIN\n"
+ "        projects p ON p.project_id = t.project_id   \n"
+ "    WHERE 1=1\n"
+ "        -- and etm.active != 0\n"
+ "        AND t.is_active != 'N'\n"
+ "        AND e.employmentstatus != 'InActive'\n"
+ "        and p.po_project_type = 'TNM'\n"
+ "        AND p.active != 'false'\n"
+ "        AND etm.resource_overview_id IS NOT NULL\n"
+ "    GROUP BY \n"
+ "        etm.resource_overview_id\n"
+ "),\n"
+ "\n"
+ "TotalRequirements AS (\n"
+ "	select dept_id, project_id, sum(required_count) as required_count from \n"
+ "	(    SELECT distinct \n"
+ "			d.dept_id, \n"
+ "			rp.project_id,\n"
+ "			rr.count AS required_count,\n"
+ "			role\n"
+ "		FROM\n"
+ "			RelevantProjects rp\n"
+ "		INNER JOIN\n"
+ "			resource_requirement rr ON rp.project_id = rr.project_id \n"
+ "			inner join department d on d.name = rr.department \n"
+ "	) req\n"
+ "		GROUP BY\n"
+ "			dept_id, project_id\n"
+ "),\n"
+ "\n"
+ "UnfilledPositions AS (\n"
+ "    SELECT\n"
+ "        rp.project_id,\n"
+ "        SUM(GREATEST(0, rr.count - IFNULL(fc.filled_count, 0))) AS unfilled_count\n"
+ "    FROM\n"
+ "        RelevantProjects rp\n"
+ "    INNER JOIN\n"
+ "        resource_requirement rr ON rp.project_id = rr.project_id\n"
+ "    LEFT JOIN\n"
+ "        FilledCounts fc ON rr.resource_overview_id = fc.resource_overview_id\n"
+ "    GROUP BY \n"
+ "        rp.project_id\n"
+ ")\n"
+ "\n"
+ "SELECT distinct rp.* \n"
+ "FROM \n"
+ "    RelevantProjects rp \n"
+ "INNER JOIN\n"
+ "    TotalRequirements tr ON rp.project_id = tr.project_id\n"
+ "INNER JOIN \n"
+ "    UnfilledPositions up ON rp.project_id = up.project_id\n"
+ "    where IFNULL(tr.required_count, 0) > IFNULL(up.unfilled_count, 0)\n"
+ "    and rp.dept_id in (:deptIds) \n"
+ "    and up.unfilled_count > 0 \n"
+ "ORDER BY\n"
+ "    rp.project_name" , nativeQuery = true)
public List<Object[]> getAllUnfilledPositionList(List<Long> deptIds);

@Query(value = "SELECT\n"
+ " distinct p.project_id,project_name,\n "
+ " GROUP_CONCAT(DISTINCT ppd.po_no ORDER BY p.start_date   SEPARATOR ', ') AS po_no,\n" 
+ "p.client_id, p.po_project_id, p.active,po_project_type,\n"
+ "			     GROUP_CONCAT(DISTINCT e1.name ORDER BY e1.name SEPARATOR ', ') as Project_Manager,\n"
+ "			     c.client_name,\n"
+ "GROUP_CONCAT(DISTINCT ppd.client_rm ORDER BY p.start_date SEPARATOR ', ') AS clientrm,\n"
+ " p.dept_id,\n"
+ " GROUP_CONCAT(DISTINCT ppd.apmosys_rm ORDER BY p.start_date SEPARATOR ', ') AS apmosysrm,\n " 
+ " date(p.start_date) start_date, date(p.end_date) end_date,\n"
+ "			     p.state, p.created_on, p.status PO_project_status,p.project_completion_date,p.project_status Ishine_project_status, p.internal_project_type,\n"
+ "			      CASE \n"
+ "			     WHEN p.is_draft_project = 'true' THEN 'Pending For Approval' \n"
+ "			     WHEN p.is_draft_project = 'false' THEN 'Approved' \n"
+ "			     WHEN p.is_draft_project = 'Rejected' THEN 'Rejected' \n"
+ "			     WHEN p.is_draft_project = 'Completed' THEN 'Completed' \n"
+ "			     WHEN p.is_draft_project = null THEN 'Not Started' \n"
+ "			     ELSE 'Un Mentioned Test Data' \n"
+ "			     END as Approval_status, \n"
+ "			      CASE \n"
+ "			       WHEN p.po_project_id IS NOT NULL THEN CONCAT('po', p.po_project_id)\n"
+ "			       ELSE CAST(p.project_id AS CHAR) \n"
+ "			       END AS projectViewId , \n"
+ "			     GROUP_CONCAT(DISTINCT d.name ORDER BY d.name SEPARATOR ', ') AS department_names\n"
+ "			      FROM projects p\n"
+ "LEFT JOIN project_po_details ppd \n" 
+ "ON ppd.project_id = p.project_id and ppd.active = true \n" 
+ "AND ppd.po_start_date <= current_timestamp \n" 
+ "AND ( (ppd.po_end_date IS NULL OR ppd.po_end_date >= current_timestamp) \n"
+ " or \n" 
+ " (\n"  //
+ " ppd.po_end_date < current_timestamp() \n"  //
+ " and not exists( \n" 
+ " select 1 from project_po_details ppd1\n" 
+ " where ppd1.project_id = ppd.project_id\n"
+ " and ppd1.po_start_date <= current_timestamp()\n" 
+ " and (ppd1.po_end_date is null or ppd1.po_end_date >= current_timestamp())\n" 
+ " )\n" 
+ " and DATE(ppd.po_end_date) = (\n" 
+ " Select distinct Max(DATE(ppd0.po_end_date))\n" 
+ " FROM project_po_details ppd0\n" 
+ "              WHERE ppd0.project_id = ppd.project_id\n" 
+ "                AND ppd0.po_end_date < current_timestamp()\n" 
+ " )\n" 
+ " ))\n"
// + "				  inner join po_department_mapping pdm on pdm.po_id = ppd.po_id \n"
// + "			      inner JOIN project_department_map pd ON p.project_id = pd.project_id\n"
+ "inner join po_department_mapping pdm on \n"
			+ "( (ppd.po_id IS NOT NULL AND pdm.po_id = ppd.po_id)\n" 
			+ "OR (ppd.po_id IS NULL AND pdm.project_id = p.project_id) ) \n"
+ "			      inner JOIN department d ON pdm.dept_id = d.dept_id \n"
+ "			      inner JOIN teams t ON p.project_id = t.project_id \n"
+ "			      inner JOIN employee_team_mapping etm ON t.team_id = etm.team_id \n"
+ "			      LEFT JOIN clients c ON p.client_id = c.client_id \n"
+ "			      LEFT JOIN project_manager_mapping pm on p.project_id = pm.project_id\n"
+ "			      LEFT JOIN employee e1 on e1.emp_id = pm.project_manager_id\n"
+ "			      LEFT JOIN job_role j1 on j1.job_role_id = e1.job_role_id \n"
+ "			      LEFT JOIN department d1 on d1.dept_id = j1.dept_id\n"
+ "			      WHERE 1=1\n"
+ "                 and etm.active != 0 AND t.is_active != 'N' AND p.active != 'false'\n"
+ "			         and d.dept_id in (:deptIds)\n"
+ "					 and p.po_project_type = 'Monitoring'\n"
+ "				 GROUP BY\n"
+ "			     p.project_id,project_name,p.client_id, p.po_project_id, p.active, po_project_type, c.client_name, p.dept_id, \n"
+ "			     start_date, end_date, p.state, p.created_on, p.status,p.project_completion_date,p.project_status, \n"
+ "			     p.internal_project_type" , nativeQuery = true)
public List<Object[]> getAllMonitoringList(List<Long> deptIds);


